// Datos INVENTADOS para probar el flujo sin un vuelo real. No son de ningún lote.
return [{ json: {
  vuelo: {
    id: '00000000-0000-4000-8000-000000000000',
    nombre: 'PRUEBA - Vuelo lote norte',
    lote: 'La Esperanza (datos de prueba)',
    fecha: '2026-11-12',
    notas: null,
    alturaRelativaM: 80,
    rtkFijoPct: 92.5,
    cantidadCapturas: 42,
  },
  analisis: {
    generadoEn: '2026-11-14T15:30:00-05:00',
    indices: [
      { nombre: 'NDVI', formula: '(NIR - R) / (NIR + R)', media: 0.71, mediana: 0.74, p10: 0.42, p90: 0.85, umbral: 0.5, areaBajoUmbralPct: 12.4 },
      { nombre: 'NDRE', formula: '(NIR - RE) / (NIR + RE)', media: 0.38, mediana: 0.4, p10: 0.21, p90: 0.51, umbral: 0.3, areaBajoUmbralPct: 18.9 },
      { nombre: 'GNDVI', formula: '(NIR - G) / (NIR + G)', media: 0.62, mediana: 0.64, p10: 0.4, p90: 0.77, umbral: 0.45, areaBajoUmbralPct: 9.7 },
    ],
    zonas: [
      { id: 'Z1', descripcion: 'Franja con vigor bajo en el borde oriental del lote', severidad: 'alta', indice: 'NDVI', valor: 0.38, ubicacion: { lat: 5.5012, lon: -75.8123 } },
      { id: 'Z2', descripcion: 'Mancha de vigor reducido cerca del centro', severidad: 'media', indice: 'NDRE', valor: 0.24, ubicacion: { lat: 5.5008, lon: -75.813 } },
      { id: 'Z3', descripcion: 'Zona aislada con valores algo bajos en la esquina sur', severidad: 'baja', indice: 'GNDVI', valor: 0.43, ubicacion: null },
    ],
    observaciones: ['Los valores bajos se concentran hacia el borde oriental.', 'La foto RGB de la zona Z2 muestra follaje más claro que el entorno.'],
    confianza: 'media',
    limitaciones: ['Datos de prueba inventados: no corresponden a un vuelo real.'],
  },
} }];

// El flujo 02 devuelve {vuelo, analisis}; aquí se le vuelve a pegar la configuración de este flujo.
const config = $('Configuración').first().json.config;
const r = $input.first().json;
return [{ json: { vuelo: r.vuelo, analisis: r.analisis, config, mapasInforme: Array.isArray(r.mapasInforme) ? r.mapasInforme : [] } }];

// Valida la entrada y arma los mensajes para el modelo de redacción.
const entrada = $input.first().json;
const { vuelo, analisis, config } = entrada;

const errores = [];
if (!vuelo || typeof vuelo !== 'object') errores.push('Falta "vuelo".');
else {
  if (!vuelo.id) errores.push('Falta vuelo.id.');
  if (!vuelo.nombre) errores.push('Falta vuelo.nombre.');
}
if (!analisis || !Array.isArray(analisis.indices) || analisis.indices.length === 0) {
  errores.push('Falta analisis.indices (al menos un índice).');
}
if (errores.length) throw new Error('Entrada inválida: ' + errores.join(' '));

const sistema = [
  'Eres un asistente que redacta informes técnicos de análisis multiespectral de cultivos de café a partir de datos ya calculados.',
  '',
  'Reglas obligatorias:',
  '1. Usa SOLO las cifras que aparecen en los datos. No calcules, no redondees de otra forma y no conviertas unidades ni porcentajes (por ejemplo, no pases 0,124 a 12,4 %). Si citas una cifra, cópiala igual.',
  '2. No diagnostiques enfermedades, plagas ni deficiencias: un índice bajo indica vigor reducido, no su causa. Di que la causa debe confirmarse en campo.',
  '3. Las recomendaciones son verificaciones en campo que haría un agrónomo (visitar la zona, tomar muestras, comparar con zonas sanas). No menciones productos, dosis ni tratamientos.',
  '4. Si falta un dato necesario, indícalo en "limitaciones" y no lo supongas.',
  'En el título usa el nombre del vuelo (vuelo.nombre), nunca su identificador.',
  'En "limitaciones" no repitas las que ya vienen en analisis.limitaciones ni en analisis.correlacionApp.limitaciones: añade solo limitaciones nuevas.',
  '5. Escribe en español claro y profesional, sin relleno ni frases de cortesía.',
  'Sobre plantas: no se te entrega ningún conteo ni densidad detectada con el dron; no los menciones ni los calcules. Del marco de siembra solo existe la densidad teórica (provisional); no la presentes como densidad real ni la uses para afirmar fallas de siembra. El informe ya incluye una sección propia, rotulada como estimación experimental.',
  '6. Responde ÚNICAMENTE con un objeto JSON con exactamente esta forma, sin texto adicional ni bloques de código:',
  '{"titulo":"...","resumenEjecutivo":"... (hasta 120 palabras)","hallazgos":[{"titulo":"...","detalle":"...","severidad":"alta|media|baja|informativa","referencia":"id de zona o nombre del índice"}],"interpretacionIndices":[{"indice":"...","lectura":"..."}],"recomendaciones":["..."],"limitaciones":["..."]}',
].join('\n');

// Los polígonos de las zonas no se envían al modelo: gastan tokens y el PDF no los muestra
// El conteo de copas y la densidad detectada NO se envían al modelo: son estimaciones sin validar y el modelo las presentaba
// como densidad real. El PDF las imprime directamente, con su etiqueta de estimación experimental.
const { huellas: _huellas, plantas: _plantas, ...analisisBase } = analisis;
if (analisisBase.siembra) { const { plantasPorHaDetectada: _a, diferenciaPct: _b, ...siembraTeorica } = analisisBase.siembra; analisisBase.siembra = siembraTeorica; }
const correlacionSinCeldas = analisis.correlacionApp ? (({ celdas, ...c }) => c)(analisis.correlacionApp) : analisis.correlacionApp;
const sinPoligonos = { ...analisisBase, correlacionApp: correlacionSinCeldas, zonas: Array.isArray(analisis.zonas) ? analisis.zonas.map(({ poligono, ...z }) => z) : analisis.zonas };
const datos = { vuelo, analisis: sinPoligonos };
const usuario = 'Datos del vuelo y del análisis (JSON):\n' + JSON.stringify(datos, null, 1) + '\n\nRedacta el informe.';

return [{ json: { config, datos, completo: { vuelo, analisis }, sistema, usuario } }];

// Interpreta la respuesta del modelo, valida su forma y revisa que las cifras salgan de los datos.
// Si el modelo no está disponible (límite de uso, error, respuesta inválida) se arma el informe solo con las cifras calculadas.
const interpretar = () => {
const resp = $input.first().json;
if (resp.statusCode !== 200) {
  const detalle = resp.body && resp.body.error && resp.body.error.message ? resp.body.error.message : JSON.stringify(resp.body);
  throw new Error('El modelo respondió ' + resp.statusCode + ': ' + String(detalle).slice(0, 300));
}

const previo = $('Validar y preparar').first().json;
const eleccion = resp.body.choices && resp.body.choices[0] ? resp.body.choices[0] : {};
let texto = eleccion.message && typeof eleccion.message.content === 'string' ? eleccion.message.content : '';
texto = texto.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
if (!texto) {
  throw new Error('El modelo no devolvió texto (finish_reason: ' + (eleccion.finish_reason || '?') + '). Sube max_tokens o baja el razonamiento.');
}

const ini = texto.indexOf('{');
const fin = texto.lastIndexOf('}');
if (ini < 0 || fin < ini) throw new Error('La respuesta del modelo no contiene un JSON.');
let crudo;
try {
  crudo = JSON.parse(texto.slice(ini, fin + 1));
} catch (e) {
  throw new Error('El JSON del modelo no es válido: ' + e.message);
}

const SEVERIDADES = ['alta', 'media', 'baja', 'informativa'];
const txt = (v) => (typeof v === 'string' ? v.trim() : '');
const lista = (v) => (Array.isArray(v) ? v : []);
const informe = {
  titulo: txt(crudo.titulo) || 'Informe de análisis multiespectral',
  resumenEjecutivo: txt(crudo.resumenEjecutivo),
  hallazgos: lista(crudo.hallazgos)
    .map((h) => ({ titulo: txt(h && h.titulo), detalle: txt(h && h.detalle), severidad: h && SEVERIDADES.includes(h.severidad) ? h.severidad : 'informativa', referencia: txt(h && h.referencia) }))
    .filter((h) => h.titulo || h.detalle),
  interpretacionIndices: lista(crudo.interpretacionIndices)
    .map((i) => ({ indice: txt(i && i.indice), lectura: txt(i && i.lectura) }))
    .filter((i) => i.indice && i.lectura),
  recomendaciones: lista(crudo.recomendaciones).map(txt).filter(Boolean),
  limitaciones: lista(crudo.limitaciones).map(txt).filter(Boolean),
};
if (!informe.resumenEjecutivo) throw new Error('El informe del modelo no trae resumen ejecutivo.');

// Comprobación de cifras: todo número del texto debe existir en los datos de entrada
const redondeo = (n) => Number(n.toFixed(2));
const permitidos = new Set();
const permitir = (n) => {
  if (!Number.isFinite(n)) return;
  permitidos.add(redondeo(n));
  permitidos.add(redondeo(n * 100));
  permitidos.add(redondeo(n / 100));
};
for (const m of JSON.stringify(previo.datos).matchAll(/\d+(?:\.\d+)?/g)) permitir(parseFloat(m[0]));

const desconocidos = new Set();
for (const m of JSON.stringify(informe).matchAll(/\d+(?:[.,]\d+)?/g)) {
  const n = parseFloat(m[0].replace(',', '.'));
  if (!Number.isFinite(n)) continue;
  if (Number.isInteger(n) && n <= 10) continue;
  if (Number.isInteger(n) && n >= 1900 && n <= 2100) continue;
  if (!permitidos.has(redondeo(n))) desconocidos.add(m[0]);
}
const advertencias = desconocidos.size ? ['Cifras del texto que no aparecen en los datos: ' + [...desconocidos].join(', ')] : [];

const uso = resp.body.usage || {};
const consumo = {
  entrada: uso.prompt_tokens || 0,
  salida: uso.completion_tokens || 0,
  razonamiento: (uso.completion_tokens_details && uso.completion_tokens_details.reasoning_tokens) || 0,
};

return [{ json: { config: previo.config, datos: previo.datos, informe, advertencias, consumo } }];
};

const informeSinModelo = (motivo) => {
  const previo = $('Validar y preparar').first().json;
  const { vuelo, analisis } = previo.datos;
  const idx = Array.isArray(analisis.indices) ? analisis.indices : [];
  const zonas = Array.isArray(analisis.zonas) ? analisis.zonas : [];
  const informe = {
    titulo: 'Informe de análisis multiespectral — ' + vuelo.nombre,
    resumenEjecutivo: 'Informe preparado solo con las cifras calculadas del vuelo «' + vuelo.nombre + '»: el modelo de IA que redacta el análisis no estuvo disponible en este momento, por lo que no incluye interpretación redactada. ' +
      idx.map((i) => i.nombre + ' medio ' + i.media).join('; ') + '. ' +
      (zonas.length ? 'Se identificaron ' + zonas.length + ' zonas con vigor reducido; su ubicación y valores están en las tablas y mapas.' : 'No se identificaron zonas con vigor reducido.'),
    hallazgos: [],
    interpretacionIndices: idx.map((i) => ({ indice: i.nombre, lectura: 'Media ' + i.media + ', mediana ' + i.mediana + '; ' + i.areaBajoUmbralPct + ' % del área de las capturas bajo el umbral ' + i.umbral + '.' })),
    recomendaciones: [
      'Visitar en campo las zonas señaladas y compararlas con zonas de vigor alto del mismo lote.',
      'Confirmar en campo la causa de cualquier vigor reducido: los índices no identifican enfermedades, plagas ni deficiencias.',
    ],
    limitaciones: ['Este informe no incluye la redacción del modelo de IA porque no estuvo disponible (' + String(motivo).slice(0, 120) + ').'],
  };
  return [{ json: { config: previo.config, datos: previo.datos, informe, advertencias: ['El modelo de redacción no estuvo disponible: el informe usa solo cifras calculadas. Vuelve a generarlo más tarde para obtener la redacción completa.'], consumo: { entrada: 0, salida: 0, razonamiento: 0 } } }];
};

try {
  return interpretar();
} catch (error) {
  return informeSinModelo(error && error.message ? error.message.replace(/\s+/g, ' ') : 'error desconocido');
}

// Arma el HTML del informe (todo el texto se escapa) y le pone un nombre de archivo imposible de adivinar.
const d = $input.first().json;
const { config, datos, informe, advertencias, consumo } = d;
const { vuelo, analisis } = datos;
// `datos` va sin conteo de copas ni celdas (no se envían al modelo); el PDF lee la copia completa.
const completo = (() => { try { return $('Validar y preparar').first().json.completo || null; } catch (e) { return null; } })();

const esc = (v) => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const fechaLarga = (iso) => {
  const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(iso || ''));
  return m ? `${Number(m[3])} de ${MESES[Number(m[2]) - 1]} de ${m[1]}` : String(iso || '');
};
const num = (v, dec = 2) => (typeof v === 'number' && Number.isFinite(v) ? String(Number(v.toFixed(dec))).replace('.', ',') : '');

// Unifica decimales en los textos redactados: coma decimal; los valores 0,xxx (índices) a dos decimales.
// No toca coordenadas (4+ decimales) ni miles escritos con punto (3,909 plantas) porque solo actúa si la parte entera es 0 o si hay 1-2 decimales.
const decimales = (t) => String(t ?? '')
  .replace(/(?<![\d.,])(-|−)?0[.,](\d{3,4})(?!\d)/g, (m, s, f) => `${s || ''}${(Math.round(Number('0.' + f) * 100) / 100).toFixed(2).replace('.', ',')}`)
  .replace(/(?<![\d.,])(\d+)\.(\d{1,2})(?!\d|\.\d)/g, '$1,$2');
const TIPO = {
  med: '<span class="tipo tipo-med">Medición</span>',
  est: '<span class="tipo tipo-est">Estimación</span>',
  pen: '<span class="tipo tipo-pen">Pendiente</span>',
};

// Identificador aleatorio de 48 caracteres hexadecimales: es la "llave" del enlace de descarga
let secreto;
if (globalThis.crypto && typeof globalThis.crypto.getRandomValues === 'function') {
  const bytes = new Uint8Array(24);
  globalThis.crypto.getRandomValues(bytes);
  secreto = Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
} else {
  secreto = require('crypto').randomBytes(24).toString('hex'); // necesita NODE_FUNCTION_ALLOW_BUILTIN=crypto (ya está en el docker-compose)
}
const expira = new Date(Date.now() + config.horasVigencia * 3600 * 1000);
// La fecha de vencimiento va dentro del nombre: así el flujo de descarga puede comprobarla sin guardar nada más
const informeId = `${Math.floor(expira.getTime() / 1000)}-${secreto}`;
const archivo = informeId + '.pdf';
const base = String(config.urlPublica).replace(/\/+$/, '');
const enlace = `${base}/webhook/informe?t=${informeId}`;

const filaMeta = (k, v) => (v === null || v === undefined || v === '' ? '' : `<tr><th>${esc(k)}</th><td>${esc(v)}</td></tr>`);
const meta = [
  filaMeta('Vuelo', vuelo.nombre),
  filaMeta('Lote', vuelo.lote),
  filaMeta('Fecha del vuelo', vuelo.fecha ? fechaLarga(vuelo.fecha) : ''),
  filaMeta('Altura relativa', typeof vuelo.alturaRelativaM === 'number' ? `${num(vuelo.alturaRelativaM, 1)} m` : ''),
  filaMeta('RTK fijo', typeof vuelo.rtkFijoPct === 'number' ? `${num(vuelo.rtkFijoPct, 1)} %` : ''),
  filaMeta('Capturas analizadas', typeof vuelo.cantidadCapturas === 'number' ? vuelo.cantidadCapturas : ''),
  filaMeta('Confianza del análisis', analisis.confianza),
  filaMeta('Notas', vuelo.notas),
].join('');

const filasIndices = analisis.indices.map((i) => `<tr>
  <td><strong>${esc(i.nombre)}</strong><br><span class="peq">${esc(i.formula)}</span></td>
  <td class="n">${num(i.media)}</td><td class="n">${num(i.mediana)}</td><td class="n">${num(i.p10)}</td><td class="n">${num(i.p90)}</td>
  <td class="n">${esc(i.desviacion == null ? "no disponible" : num(i.desviacion))}</td><td class="n">${esc(i.cv == null ? "no disponible" : num(i.cv))}</td>
  <td class="n">${num(i.umbral)}</td><td class="n">${num(i.areaBajoUmbralPct, 1)}${typeof i.areaBajoUmbralPct === 'number' ? ' %' : ''}</td></tr>`).join('');

const zonas = Array.isArray(analisis.zonas) ? analisis.zonas : [];
const filasZonas = zonas.map((z) => {
  const ub = z.ubicacion && typeof z.ubicacion.lat === 'number' && typeof z.ubicacion.lon === 'number' ? `${z.ubicacion.lat.toFixed(5)}, ${z.ubicacion.lon.toFixed(5)}` : '—';
  return `<tr><td><strong>${esc(z.id)}</strong></td><td>${esc(z.descripcion)}</td><td><span class="sev sev-${esc(z.severidad)}">${esc(z.severidad)}</span></td><td>${esc(z.indice)}</td><td class="n">${num(z.valor)}</td><td class="peq">${esc(ub)}</td><td class="n">${num(z.areaM2, 0) || '—'}</td></tr>`;
}).join('');

const hallazgos = informe.hallazgos.map((h) => `<div class="hallazgo">
  <div class="hh"><span class="sev sev-${esc(h.severidad)}">${esc(h.severidad)}</span> <strong>${esc(h.titulo)}</strong>${h.referencia ? ` <span class="peq">(${esc(h.referencia)})</span>` : ''}</div>
  <p>${esc(decimales(h.detalle))}</p></div>`).join('');

const lecturas = informe.interpretacionIndices.map((i) => `<p><strong>${esc(i.indice)}.</strong> ${esc(decimales(i.lectura))}</p>`).join('');
const li = (arr) => arr.map((t) => `<li>${esc(decimales(t))}</li>`).join('');
const observaciones = Array.isArray(analisis.observaciones) ? analisis.observaciones.filter((t) => typeof t === 'string' && t.trim()) : [];
const limitaciones = [...new Set([...(Array.isArray(analisis.limitaciones) ? analisis.limitaciones : []), ...informe.limitaciones].filter((t) => typeof t === 'string' && t.trim()))];

const aviso = advertencias.length
  ? `<div class="revisar"><strong>Revisar antes de usar este informe:</strong><ul>${li(advertencias)}</ul></div>`
  : '';

const pct = (v) => (typeof v === 'number' && Number.isFinite(v) ? `${num(v, 1)} %` : 'no disponible');
const vg = analisis.vigor;
const bloqueVigor = vg ? `<h2>Distribución del vigor (NDVI) ${TIPO.med}</h2>
<table><thead><tr><th>Clase</th><th>Criterio</th><th>Porcentaje</th></tr></thead><tbody>
<tr><td>Vigor alto</td><td>NDVI desde ${num(vg.umbralAlto)}</td><td class="n">${pct(vg.altoPct)}</td></tr>
<tr><td>Vigor intermedio</td><td>NDVI entre ${num(vg.umbralBajo)} y ${num(vg.umbralAlto)}</td><td class="n">${pct(vg.medioPct)}</td></tr>
<tr><td>Vigor bajo</td><td>NDVI bajo ${num(vg.umbralBajo)}</td><td class="n">${pct(vg.bajoPct)}</td></tr></tbody></table>
<p class="peq">Es el porcentaje de píxeles de las capturas analizadas, no el porcentaje de plantas afectadas. Los cortes de NDVI son provisionales y deben calibrarse con el cultivo y su etapa.</p>` : '';
const cv = analisis.cobertura;
const sb = (completo && completo.analisis && completo.analisis.siembra) || analisis.siembra;
const filasLote = [
  cv ? `<tr><th>Cobertura vegetal (NDVI desde ${num(cv.umbralNdvi)})</th><td>${pct(cv.pct)}</td></tr>` : '',
  sb ? `<tr><th>Marco de siembra</th><td>${num(sb.distSurcoM, 1)} m entre surcos × ${num(sb.distPlantaM, 1)} m entre plantas${sb.provisional ? ' (valor provisional)' : ''}</td></tr>` : '',
  sb && sb.variedad ? `<tr><th>Variedad</th><td>${esc(sb.variedad)}</td></tr>` : '',
  sb && typeof sb.alturaPlantaM === 'number' ? `<tr><th>Altura de planta</th><td>${num(sb.alturaPlantaM, 1)} m</td></tr>` : '',
  sb ? `<tr><th>Densidad teórica</th><td>${num(sb.plantasPorHaTeorica, 0)} plantas por hectárea</td></tr>` : '',
  sb ? `<tr><th>Densidad detectada con el dron</th><td>${typeof sb.plantasPorHaDetectada === 'number' ? `${num(sb.plantasPorHaDetectada, 0)} copas por hectárea${typeof sb.diferenciaPct === 'number' ? ` (${num(sb.diferenciaPct, 1)} % frente a la teórica)` : ''} — estimación experimental sin validar, ver «Conteo de copas»` : 'No calculada (sin capturas cenitales con GSD)'}</td></tr>` : '',
  `<tr><th>Diagnóstico fitosanitario</th><td>Pendiente: requiere inspección en campo</td></tr>`,
  `<tr><th>Proyección de propagación</th><td>No calculable con una sola captura o fecha. Requiere al menos dos vuelos comparables, confirmación de la causa en campo y un modelo validado.</td></tr>`,
].join('');
const bloqueLote = `<h2>Cobertura, siembra y estado del diagnóstico ${TIPO.med} ${TIPO.est} ${TIPO.pen}</h2><table class="meta">${filasLote}</table>`;

// Los datos nuevos se presentan directamente; ningún valor procede del modelo.
const disponible = (v) => v == null ? 'no disponible' : v;
const filaDato = (k, v) => filaMeta(k, disponible(v));
const rango = (v) => v == null ? null : `${disponible(v.min)} — ${disponible(v.max)}`;
const ficha = analisis.ficha;
const bloqueFicha = `<h2>Ficha técnica del vuelo ${TIPO.med}</h2><table class="meta">${[
  filaDato('Sensores', ficha?.sensores?.join(', ')),
  filaDato('Resoluciones (ancho × alto, píxeles)', ficha?.resolucionesPx?.map((r) => `${disponible(r.ancho)} × ${disponible(r.alto)}`).join('; ')),
  filaDato('Bandas disponibles', ficha?.bandasDisponibles?.join(', ')),
  filaDato('Altura relativa (mínima — máxima, m)', rango(ficha?.alturaRelativaM)),
  filaDato('Capturas usadas', ficha?.capturasUsadas),
  filaDato('Capturas con georreferencia', ficha?.capturasConGeorreferencia),
  filaDato('Capturas calibradas', ficha?.calibracion?.calibradas),
  filaDato('Capturas sin calibrar', ficha?.calibracion?.sinCalibrar),
  filaDato('Fecha de captura (mínima — máxima)', rango(ficha?.fechaCaptura)),
  filaDato('GSD usado (cm/píxel, mín — máx)', ficha?.gsdCmPx ? `${num(ficha.gsdCmPx.min, 2)} — ${num(ficha.gsdCmPx.max, 2)}` : null),
